//! Bounded experiment-design research copilot for Worldgen P09 F09-F12.
use std::collections::BTreeSet;
use super::experiment_design_support::{self,ExperimentDesignQuestion,ExperimentDesignPortfolio};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.experiment-design-copilot-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ExperimentDesignCopilotRequest{pub design_request:ExperimentDesignQuestion,pub action_order:Vec<String>,pub action_budget:u64,pub dry_run:bool,pub signed_approval:bool,pub federation_approved:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ExperimentDesignCopilotReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub question_id:String,pub disposition:String,pub action_order:Vec<String>,pub admitted_action_order:Vec<String>,pub denied_action_order:Vec<String>,pub experiment_design_disposition:String,pub portfolio_digest:ContentHash,pub copilot_digest:ContentHash,pub replay_identity:ContentHash,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ExperimentDesignCopilotError{#[error("invalid experiment design copilot request: {0}")]Invalid(String),#[error("experiment_design control failed: {0}")]Design(String),#[error("experiment design copilot artifact failed: {0}")]Artifact(String),#[error("invalid experiment design copilot receipt: {0}")]Receipt(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn s(v:Vec<String>)->Vec<String>{let mut o=v;o.sort();o.dedup();o}
impl ExperimentDesignCopilotReceipt{pub fn validate(&self)->Result<(),ExperimentDesignCopilotError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.question_id.trim().is_empty()||self.action_order.is_empty()||self.effect_receipts.is_empty()||![&self.portfolio_digest,&self.copilot_digest,&self.replay_identity].into_iter().all(h){return Err(ExperimentDesignCopilotError::Receipt("experiment design copilot identity, actions, locality, digests, or effects are incomplete".into()));}for v in [&self.action_order,&self.admitted_action_order,&self.denied_action_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(ExperimentDesignCopilotError::Receipt("experiment design copilot vectors are not canonical".into()));}}let actions=self.action_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.admitted_action_order.iter().chain(&self.denied_action_order).cloned().collect::<Vec<_>>();if actions.len()!=self.action_order.len()||parts.len()!=actions.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=actions{return Err(ExperimentDesignCopilotError::Receipt("experiment design copilot actions do not partition".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.copilot_digest.as_str()){return Err(ExperimentDesignCopilotError::Receipt("experiment design copilot artifact digest is inconsistent".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["experiment_design steward","preclinical researcher","workflow operator"],"behavior":format!("run bounded experiment-design actions for {scale}"),"value":"turns ranked experiment_designs into an approval-bounded product without exposing protected experiment_designs","input_schema":input_schema,"output_schema":"ExperimentDesignCopilotReceipt1@1","effects":["invoke:bounded-experiment_design-tool","block:unsafe-release"],"permissions":["invoke:declared-experiment_design-tool"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn run(request:&ExperimentDesignCopilotRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<ExperimentDesignCopilotReceipt,ExperimentDesignCopilotError>{if request.boundary!=PRECLINICAL_BOUNDARY||request.action_order.is_empty()||request.action_budget==0||request.action_order!=s(request.action_order.clone())||!request.design_request.raw_data_local||!request.design_request.aggregate_only{return Err(ExperimentDesignCopilotError::Invalid("experiment design copilot boundary, action, budget, locality, or ordering is invalid".into()));}let discovery=experiment_design_support::design(&request.design_request,feature_id,version,scale,require_federation).map_err(|e|ExperimentDesignCopilotError::Design(e.to_string()))?;let mut omissions=discovery.omissions.clone();let approved=(!require_approval||request.signed_approval)&&(!require_federation||request.federation_approved);if !approved{omissions.push("copilot:approval-missing".into());}if request.dry_run{omissions.push("copilot:dry-run-no-effect".into());}if request.action_order.len()as u64>request.action_budget{omissions.push("copilot:action-budget-exceeded".into());}let safe=discovery.disposition=="qualified"&&approved&&request.action_order.len()as u64<=request.action_budget;let disposition=if safe{"qualified"}else if discovery.disposition=="blocked"||!approved{"blocked"}else{"partial"};let admitted=if safe{request.action_order.clone()}else{Vec::new()};let denied=if safe{Vec::new()}else{request.action_order.clone()};let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("invoke:bounded-experiment-design-tool:{}",request.design_request.objective)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"question_id":request.design_request.request_id,"disposition":disposition,"action_order":request.action_order,"admitted_action_order":admitted,"denied_action_order":denied,"experiment_design_disposition":discovery.disposition,"portfolio_digest":discovery.portfolio_digest,"replay_identity":discovery.replay_identity,"omissions":s(omissions),"uncertainty":discovery.uncertainty,"negative_evidence":discovery.negative_evidence,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|ExperimentDesignCopilotError::Artifact(e.to_string()))?;let r=ExperimentDesignCopilotReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),question_id:request.design_request.request_id.clone(),disposition:disposition.into(),action_order:request.action_order.clone(),admitted_action_order:admitted,denied_action_order:denied,experiment_design_disposition:discovery.disposition,portfolio_digest:discovery.portfolio_digest,copilot_digest:d.clone(),replay_identity:discovery.replay_identity,omissions:s(payload["omissions"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect()),uncertainty:discovery.uncertainty,negative_evidence:discovery.negative_evidence,effect_receipts:effects,artifact:json!({"artifact_id":format!("experiment-design-copilot:{}",request.design_request.request_id),"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};r.validate()?;Ok(r)}





